/* Extended learning workspace. Original DP routes and local-storage keys stay compatible. */
const dpLessonContent = window.DP_LEGACY.lessonContent;
const dpVisual = window.DP_LEGACY.visual;
const legacyBind = window.DP_LEGACY.bind;
const legacyBindFlash = window.DP_LEGACY.bindFlash;
const dpCategories=['1D DP','Grid DP','Subsequences','Strings','Stocks','LIS','Partition DP','Rectangles'];
const ncCategories=['Arrays & Hashing','Two Pointers','Sliding Window','Stack','Binary Search','Linked List','Trees','Heap / Priority Queue','Backtracking','Tries','Graphs','Advanced Graphs','1-D Dynamic Programming','2-D Dynamic Programming','Greedy','Intervals','Math & Geometry','Bit Manipulation'];
let currentTrack='neetcode',lastLessonId=null;
try{currentTrack=localStorage.getItem('pattern-studio-track')==='dp'?'dp':'neetcode';}catch{}
const trackName=()=>currentTrack==='dp'?"Striver’s DP":"NeetCode 150";
const trackData=()=>data.filter(p=>p.track===currentTrack);
const topicKeys=()=>currentTrack==='dp'?dpCategories:ncCategories;
const lessonNumber=p=>p.track==='dp'?`DP ${String(p.id).padStart(2,'0')}`:`NC ${String(p.sequence).padStart(3,'0')}`;
function route(){const parts=location.hash.slice(1).split('/');let slug='';try{slug=decodeURIComponent(parts.slice(1).join('/'))}catch{}return {page:parts[0]||'library',id:Number(parts[1]),slug};}
function selectTrack(track){stop();currentTrack=track;category='All';search='';status=difficulty='all';flashIndex=0;flipped=false;try{localStorage.setItem('pattern-studio-track',track)}catch{}if(route().page!=='library')go('library');else render();}
function mathText(s){return String(s).replace(/\$+/g,'').replace(/\\(?:text|mathrm|mathbf|operatorname)\{([^{}]*)\}/g,'$1').replace(/\\(?:log|log_2)/g,'log').replace(/\\cdot|\\times/g,' × ').replace(/\\(?:leq|le)/g,'≤').replace(/\\(?:geq|ge)/g,'≥').replace(/\\min/g,'min').replace(/\\max/g,'max').replace(/\\sqrt\{([^}]*)\}/g,'√($1)').replace(/\\frac\{([^}]*)\}\{([^}]*)\}/g,'($1)/($2)').replace(/\\left|\\right|\\,/g,'').replace(/\^\{([^}]+)\}/g,'^($1)').replace(/\\/g,'').replace(/[{}]/g,'');}
function inline(md){return esc(mathText(md)).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1');}
function markdown(md){const lines=String(md||'').split('\n');let out='',list=null;for(const line of lines){if(/^---+$/.test(line.trim()))continue;const item=line.match(/^\s*(?:([-*])|\d+\.)\s+(.*)$/);if(item){const type=item[1]?'ul':'ol';if(list!==type){if(list)out+=`</${list}>`;out+=`<${type}>`;list=type;}out+=`<li>${inline(item[2])}</li>`;}else{if(list){out+=`</${list}>`;list=null;}if(/^###? /.test(line))out+=`<h3>${inline(line.replace(/^#+\s*/,''))}</h3>`;else if(line.trim())out+=`<p>${inline(line)}</p>`;}}if(list)out+=`</${list}>`;return out;}
function render(){disposeCinema();const r=route();const p=data.find(p=>p.id===r.id);if(r.page==='lesson'&&p){currentTrack=p.track;if(lastLessonId!==p.id){approach=p.recommended??1;lastLessonId=p.id;step=0;if(lessonTab!=='notes')lessonTab='visual';}}categories=topicKeys();const active=r.page==='lesson'?'library':r.page==='topic'?'topics':r.page;const source=currentTrack==='dp'?'https://takeuforward.org/dsa/strivers-a2z-sheet-learn-dsa-a-to-z':'https://neetcode.io/practice/practice/neetcode150';$('#app').innerHTML=`<div class="shell"><aside class="sidebar ${menuOpen?'open':''}"><a href="#library" class="brand"><span class="brand-mark">${icon('branch')}</span><span>pattern studio<small>UNDERSTAND. CONNECT. REMEMBER.</small></span></a><div class="track-switch" aria-label="Learning track"><button data-track="neetcode" class="${currentTrack==='neetcode'?'active':''}">NeetCode 150</button><button data-track="dp" class="${currentTrack==='dp'?'active':''}">Striver’s DP</button></div><nav class="nav-group" aria-label="Main navigation">${[['library','grid','Problem library'],['topics','book','Topic guides'],['flashcards','cards','Flashcards'],['notes','notes','My notes'],['saved','bookmark','Saved for later']].map(([id,i,label])=>`<button class="nav-item ${active===id?'active':''}" data-go="${id}">${icon(i)}${label}${id==='flashcards'?`<span class="count">${trackData().length*2}</span>`:''}</button>`).join('')}</nav><div><div class="nav-label">${currentTrack==='dp'?'DP PATTERNS':'TOPICS · 18 CONNECTIONS'}</div><nav class="category-nav" aria-label="Problem categories">${categories.map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c}<span>${trackData().filter(p=>p.category===c).length}</span></button>`).join('')}</nav></div><div class="side-bottom"><div class="storage"><strong>${icon('lock')} Yours, on this device</strong>Notes & progress stay in your browser. Export a backup any time.</div><a href="${source}" class="source-link sidebar-source" target="_blank" rel="noopener">Original ${trackName()} list ↗</a></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><div class="breadcrumb">Your learning space <b>/ &nbsp; ${r.page==='lesson'?esc(p?.category||'Lesson'):trackName()}</b></div><div class="topright"><span class="pill">${icon('code')} Python · no API keys</span><span class="avatar">You</span></div></header><main class="main">${localError?'<div class="notice">Browser storage is unavailable. Export a backup to keep this session’s work.</div>':''}${r.page==='lesson'?(p?lesson(p):'<div class="empty">Lesson not found. <a href="#library">Open library</a></div>'):r.page==='topics'?topicsPage():r.page==='topic'?topicPage(r.slug):r.page==='flashcards'?flashcards():r.page==='notes'?notes():library(r.page==='saved')}</main></div></div>`;bind();if(r.page==='lesson'&&p)bindLesson(p);if(r.page==='flashcards')bindFlash();}
function libraryBeforeClassroom(onlySaved=false){const items=trackData();const complete=items.filter(p=>saved.done.includes(p.id)).length;const percent=Math.round(complete/items.length*100);const last=items.find(p=>p.id===saved.last)||items.find(p=>!saved.done.includes(p.id))||items[0];return `<div class="page-heading"><div><div class="eyebrow">${trackName()} · YOUR PYTHON LEARNING PATH</div><h1>${onlySaved?'Give it another look.':'Understand the why. Remember the how.'}</h1><p>${currentTrack==='dp'?'56 lessons through dynamic programming.':'150 problems. 18 topics. One connected understanding.'}</p></div><button class="btn" data-go="flashcards">${icon('cards')} Practice recall</button></div><div class="mobile-track track-switch"><button data-track="neetcode" class="${currentTrack==='neetcode'?'active':''}">NeetCode 150</button><button data-track="dp" class="${currentTrack==='dp'?'active':''}">Striver’s DP</button></div>${onlySaved?'':`<div class="journey-strip"><div class="journey-current"><span class="journey-symbol">${icon('play')}</span><div><div class="eyebrow">PICK UP A PATTERN</div><h3>${esc(last.title)}</h3><span>${esc(last.category)} · ${last.track==='neetcode'?last.approaches.length:'4'} approaches</span></div><button class="btn lime" data-go="lesson/${last.id}">Open lesson ${icon('arrow')}</button></div><div class="journey-progress"><div class="ring" style="--percent:${percent}%"><span>${percent}%</span></div><div><strong>${complete}<small> / ${items.length}</small></strong><span>problems understood</span></div></div></div><div class="story-showcase"><div class="showcase-art" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div><span class="story-kicker">NEW · VISUAL STORIES</span><h3>See the decision. Keep the picture.</h3><p>Walk through a pattern in purposeful scenes, then test the idea from memory.</p></div><button class="btn" data-go="lesson/${currentTrack==='dp'?2:1011}">Watch a story ${icon('play')}</button></div><div class="guides-invitation"><div><span class="eyebrow">BUILD THE MENTAL MODEL FIRST</span><h3>Know what the tool does. Then know when to use it.</h3></div><button class="btn" data-go="topics">Explore topic guides ${icon('arrow')}</button></div>`}<div class="section-heading"><h2>${onlySaved?'Saved for later':category==='All'?'Problem library':category}</h2><span>${filtered(onlySaved).length} problems · ${trackName()}</span></div><section class="problem-panel"><div class="table-tools"><label class="search">${icon('search')}<input id="search" aria-label="Search problems" placeholder="Search a problem or idea…" value="${esc(search)}"></label><div class="filter-row"><select id="category-filter" aria-label="Filter category">${['All',...categories].map(c=>`<option value="${esc(c)}" ${category===c?'selected':''}>${c==='All'?'All topics':c}</option>`).join('')}</select><select id="difficulty" aria-label="Filter difficulty">${['all','Easy','Medium','Hard'].map(v=>`<option value="${v}" ${difficulty===v?'selected':''}>${v==='all'?'All levels':v}</option>`).join('')}</select><select id="status" aria-label="Filter progress">${[['all','All progress'],['todo','To learn'],['done','Completed']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="table-head"><span></span><span>PROBLEM & IDEA</span><span>TOPIC</span><span>LEVEL</span><span>SAVE</span></div><div id="rows">${rows(onlySaved)}</div><div class="table-footer"><span>Visual walkthroughs · Python solutions · Personal notes</span><button class="back" data-go="topics">Learn the concepts ${icon('arrow')}</button></div></section><p class="attribution">${currentTrack==='dp'?'56 learning units include the 55-problem DP curriculum and a matrix-chain tabulation workshop.':'NeetCode approach explanations and implementations adapted under the MIT license, with original problem paraphrases, guides, and visualizations.'} Independent companion. ${currentTrack==='neetcode'?'<a href="licenses/neetcode.txt" target="_blank">License & attribution</a>':''}</p>`;}
function filtered(onlySaved=false){return trackData().filter(p=>(!onlySaved||saved.bookmarks.includes(p.id))&&(category==='All'||p.category===category)&&(difficulty==='all'||p.difficulty===difficulty)&&(status==='all'||((status==='done')===saved.done.includes(p.id)))&&(`${p.title} ${p.pattern} ${p.category} ${p.cue||''}`.toLowerCase().includes(search.toLowerCase())));}
function rows(onlySaved){const list=filtered(onlySaved);return list.length?list.map(p=>`<div class="problem-row"><button class="check ${saved.done.includes(p.id)?'done':''}" data-done="${p.id}" aria-label="${saved.done.includes(p.id)?'Mark incomplete':'Mark complete'}: ${esc(p.title)}" aria-pressed="${saved.done.includes(p.id)}">${saved.done.includes(p.id)?icon('check'):''}</button><button class="problem-link" data-go="lesson/${p.id}">${esc(p.title)}<span class="story-badge">3D lesson</span><small>${lessonNumber(p)} &nbsp;·&nbsp; ${esc(p.pattern)}</small></button><span class="tag">${p.category}</span><span class="difficulty ${p.difficulty}">${p.difficulty}</span><button class="bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="Bookmark ${esc(p.title)}" aria-pressed="${saved.bookmarks.includes(p.id)}">${icon('bookmark')}</button></div>`).join(''):'<div class="empty">No problems match this selection.<br><button class="btn" data-action="clear-filters">Clear filters</button></div>';}
function bind(){legacyBind();document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>selectTrack(b.dataset.track));$('#category-filter')?.addEventListener('change',e=>{category=e.target.value;render()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>go('topic/'+encodeURIComponent(b.dataset.topic)));}
function topicsPage(){return `<div class="page-heading"><div><div class="eyebrow">FOUNDATIONS YOU CAN BUILD ON</div><h1>Learn the tool behind the trick.</h1><p>Definitions, mental models, recognition cues, and the reasoning that makes an algorithm correct.</p></div></div><div class="topic-grid">${categories.map((c,i)=>{const g=TOPICS[c];return `<button class="topic-card" data-topic="${c}"><span class="topic-num">${String(i+1).padStart(2,'0')}</span><span class="category-icon">${icon(g.icon)}</span><h2>${c}</h2><p>${esc(g.definition)}</p><span class="topic-footer">${trackData().filter(p=>p.category===c).length} connected problems ${icon('arrow')}</span></button>`}).join('')}</div>`;}
function topicPage(name){const g=TOPICS[name];if(!g)return '<div class="empty">Unknown topic. <a href="#topics">All guides</a></div>';const related=trackData().filter(p=>p.category===name);return `<button class="back" data-go="topics">${icon('back')} All topic guides</button><div class="topic-heading"><span class="category-icon">${icon(g.icon)}</span><div><div class="eyebrow">CONCEPT GUIDE · ${trackName()}</div><h1>${esc(name)}</h1></div></div><div class="topic-layout"><article class="card lesson-copy"><h2>What is it?</h2><p>${esc(g.definition)}</p><div class="mental-model"><span class="eyebrow">PICTURE IT THIS WAY</span><p>${esc(g.model)}</p></div><h2>When should this come to mind?</h2><ul>${g.recognize.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h2>A recipe you can reason through</h2><ol class="recipe">${g.recipe.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h2>The correctness rule: your invariant</h2><p>An invariant is a statement that remains true after every step. It connects the implementation to the proof.</p><div class="callout">${esc(g.invariant)}</div><h2>Cost and tradeoffs</h2><p>${esc(g.cost)}</p><h2>Common mistakes</h2><ul>${g.pitfalls.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h2>Connect it to another idea</h2><p>${esc(g.compare)}</p><h2>Check your understanding</h2><p>Explain the idea using a three-element example. Then change one constraint: allow duplicates, negative values, or a different output. Which part of your proof stops working?</p></article><aside><section class="memory-card"><div class="eyebrow">THE LINE TO REMEMBER</div><h2>${esc(g.memory)}</h2><p>Recall the reason behind this sentence before memorizing the code.</p></section><section class="card"><h3>See it in motion</h3><p class="notes-tip">Open a problem’s Visual lab to follow real Python state changes.</p>${related.slice(0,6).map(p=>`<button class="related-problem" data-go="lesson/${p.id}">${esc(p.title)}${icon('arrow')}</button>`).join('')}</section></aside></div>`;}
function lesson(p){const items=data.filter(x=>x.track===p.track);const idx=items.indexOf(p),prev=items[idx-1],next=items[idx+1];const nc=p.track==='neetcode';const full=lessonTab==='visual';return `<div class="lesson-top"><button class="back" data-go="library">${icon('back')} Problem library</button><div class="lesson-actions">${nc?`<a class="btn" href="${p.practice}" target="_blank" rel="noopener">Practice ↗</a>`:''}<button class="btn ${saved.done.includes(p.id)?'':'primary'}" data-done="${p.id}">${icon('check')} ${saved.done.includes(p.id)?'Completed':'Mark complete'}</button></div></div><div class="eyebrow">${trackName()} &nbsp; / &nbsp; ${lessonNumber(p)}</div><div class="lesson-heading"><h1>${esc(p.title)}</h1><span class="difficulty ${p.difficulty}">${p.difficulty}</span><button class="bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="Bookmark lesson">${icon('bookmark')}</button></div><div class="lesson-meta"><button class="back" data-topic="${p.category}">${icon('book')} ${p.category} guide</button><span>·</span><span>${nc?p.approaches.length:4} Python approaches</span></div><div class="tabs lesson-nav" role="tablist" aria-label="Lesson sections">${[['learn','Understand'],['code','Python solutions'],['visual','3D classroom'],['patterns','Remember'],['notes','My notes']].map(([id,label])=>`<button role="tab" aria-selected="${lessonTab===id}" data-tab="${id}" class="${lessonTab===id?'active':''}">${id==='visual'?icon('play')+' ':''}${label}</button>`).join('')}</div>${full?`<div class="visual-lab">${labPanel(p,true)}</div>`:`<div class="lesson-layout"><div><section class="card"><div id="lesson-content">${lessonContent(p)}</div></section>${nc?`<p class="attribution">Approach explanations and code: <a href="${p.source}" target="_blank" rel="noopener">NeetCode contributors</a>, <a href="licenses/neetcode.txt" target="_blank">MIT license</a>. Example and topic guide added for this learning workspace.</p>`:''}</div><aside class="visualizer">${labPanel(p,false)}<section class="memory-card"><div class="eyebrow">THE IDEA TO KEEP</div><p>${esc(p.stateMeaning)}</p><button class="btn" data-go="flashcards">${icon('cards')} Test your recall</button></section></aside></div>`}<div class="lesson-top lesson-pagination"><button class="back" ${prev?'':'disabled'} ${prev?`data-go="lesson/${prev.id}"`:''}>${icon('back')} Previous problem</button><button class="back" ${next?'':'disabled'} ${next?`data-go="lesson/${next.id}"`:''}>Next problem ${icon('arrow')}</button></div>`;}
function lessonContent(p){if(p.track==='dp'||lessonTab==='notes')return dpLessonContent(p);const best=p.approaches[p.recommended];if(lessonTab==='patterns')return `<div class="lesson-copy"><h2>Recognize the question behind the question.</h2><div class="callout">${esc(p.cue)}</div><h3>The topic’s memory hook</h3><p>${esc(TOPICS[p.category].memory)}</p><h3>What can go wrong?</h3>${markdown(p.pitfalls)}<h3>Recall without looking</h3><ol><li>What information must the algorithm remember?</li><li>Why can each discarded candidate never improve the answer?</li><li>What changes if you need the actual choices, not just their value?</li></ol><button class="btn" data-go="flashcards">${icon('cards')} Practice with flashcards</button></div>`;
if(lessonTab==='code'){approach=Math.min(approach,p.approaches.length-1);const a=p.approaches[approach];return `<div class="approach-tabs" role="tablist" aria-label="Solution approach">${p.approaches.map((a,i)=>`<button role="tab" aria-selected="${i===approach}" data-approach="${i}" class="${i===approach?'active':''}">${a.title}${i===p.recommended?' ★':''}</button>`).join('')}</div><div class="lesson-copy"><div class="solution-heading"><h2>${esc(a.title)}</h2>${approach===p.recommended?'<span class="recommended">RECOMMENDED TO LEARN</span>':''}</div>${markdown(a.intuition)}<h3>Follow the algorithm</h3>${markdown(a.algorithm)}</div><div class="code-wrap"><div class="code-head"><span>PYTHON · ${esc(a.title.toUpperCase())}</span><button id="copy">Copy code</button></div><pre><code>${highlight(a.code)}</code></pre></div><div class="complexity"><div>TIME<strong>${inline(a.time)}</strong></div><div>SPACE<strong>${inline(a.space)}</strong></div></div><div class="lesson-copy complexity-notes">${markdown(a.complexity)}</div>${/ListNode|TreeNode|\bNode\b|\bInterval\b/.test(a.code)?'<p class="notes-tip">Node and Interval types use the coding platform’s standard definitions. Example arrays show serialized structures; the solution operates on actual nodes.</p>':''}<div class="callout">★ marks the approach chosen for a clear, practical learning path. Other tabs include alternative tradeoffs and advanced optimizations. The Visual lab follows the starred implementation.</div>`;}
return `<article class="lesson-copy"><h2>The problem</h2><p>${esc(p.statement)}</p><div class="example">${Object.entries(p.example).map(([k,v])=>`<span>${esc(k)}</span> = ${esc(JSON.stringify(v))}`).join('<br>')}<br><span>Expected result</span> = ${esc(JSON.stringify(p.expected))}</div><h2>How to spot the pattern</h2><div class="callout">${esc(p.cue)}</div><details class="prerequisites"><summary>Concepts to know first</summary>${markdown(p.prerequisites)}<button class="back" data-topic="${p.category}">Read the ${p.category} guide ${icon('arrow')}</button></details><h2>Build the intuition</h2>${markdown(best.intuition)}<h2>Turn the idea into steps</h2>${markdown(best.algorithm)}<div class="mental-model"><span class="eyebrow">WHY THESE STEPS FIT TOGETHER</span><p>${esc(TOPICS[p.category].invariant)}</p><p>${esc(p.cue)}</p></div><h2>Start simple, then improve</h2><div class="approach-journey">${p.approaches.map((a,i)=>`<button data-approach-open="${i}"><span>${i+1}</span><strong>${esc(a.title)}</strong><small>${inline(a.time)}</small>${i===p.recommended?'<b>★</b>':''}</button>`).join('')}</div><p>Read the first approach to establish a correct baseline. Then compare what each later approach stops recomputing, what it stores, and the assumptions that make the improvement valid.</p><button class="btn primary" data-tab="visual">${icon('play')} Watch the Python run</button></article>`;}
function traceLabPanel(p,full){return `<section class="card lab-card ${full?'expanded':''}"><div class="visual-heading"><h3>${full?'Watch the idea become an algorithm.':'Follow the idea.'}</h3><span class="live-tag">${p.track==='dp'?'STATE TRACE':'PYTHON EXECUTION'}</span></div><p class="lab-subtitle">${p.track==='dp'?'Memoized states and their dependencies.':esc(p.approaches[p.recommended].title)+' · a verified example, step by step.'}${!full?` <button class="back inline-back" data-tab="visual">Expand lab ${icon('arrow')}</button>`:''}</p><div id="visual">${visual(p)}</div><div class="play-controls"><button data-action="reset" aria-label="Reset animation">${icon('reset')}</button><button data-action="prev" aria-label="Previous step">${icon('prev')}</button><button class="play" data-action="play">${icon(playing?'pause':'play')} ${playing?'Pause':'Play'}</button><button data-action="next" aria-label="Next step">${icon('next')}</button><select id="speed" aria-label="Animation speed">${[[1500,'0.5×'],[800,'1×'],[350,'2×'],[150,'4×']].map(([v,t])=>`<option value="${v}" ${v===speed?'selected':''}>${t}</option>`).join('')}</select></div><input class="scrubber" id="scrubber" aria-label="Dry run step" type="range" min="0" max="${p.trace.length-1}" value="${step}"><p class="lab-footnote">${p.track==='neetcode'?'A highlighted line is about to execute; variables show its current inputs. Return steps show the completed result.':'Use the arrows to inspect one state, or play to see the dependencies resolve.'}</p></section>`;}
function visual(p){if(p.track==='dp')return traceNarration(p)+dpVisual(p);step=Math.max(0,Math.min(step,p.trace.length-1));const e=p.trace[step];if(!e)return '<p>No steps in this example.</p>';const previous=p.trace[step-1]?.variables||{};const code=p.approaches[p.recommended].code.split('\n');const lo=Math.max(0,e.line-4),hi=Math.min(code.length,e.line+3);const vars=Object.entries(e.variables);const change=vars.filter(([k,v])=>JSON.stringify(previous[k])!==JSON.stringify(v));return `${traceNarration(p)}<div class="execution-status"><span class="step-badge">${step+1} / ${p.trace.length}</span><strong>${e.event==='return'?'Return from':'Inside'} ${esc(e.function)}()</strong></div><div class="simulation-board">${drawBoard(p,e)}</div><div class="execution-columns"><div><div class="mini-heading">${e.event==='return'?'RETURN VALUE':'NEXT LINE TO RUN'}</div><div class="trace-code">${code.slice(lo,hi).map((s,i)=>`<div class="trace-line ${lo+i+1===e.line?'active':''}"><span>${lo+i+1}</span><code>${highlight(s||' ')}</code></div>`).join('')}</div><div class="call-stack"><span>CALL STACK</span>${e.stack.map((s,i)=>`<b class="${i===e.stack.length-1?'top':''}">${esc(s)}()</b>`).join('<i>→</i>')}</div></div><div class="live-vars"><div class="mini-heading">LIVE STATE <span>Changed values glow</span></div>${vars.filter(([k])=>k!=='self').slice(0,12).map(([k,v])=>`<div class="live-var ${change.some(([key])=>key===k)?'changed':''}"><span>${esc(k)}</span><div>${valueHTML(v)}</div></div>`).join('')}${e.variables.self?`<details><summary>Object state</summary>${valueHTML(e.variables.self)}</details>`:''}</div></div>${step===p.trace.length-1?`<div class="result-ribbon">${icon('check')} Result <strong>${esc(JSON.stringify(p.traceResult))}</strong></div>`:''}`;}
function valueHTML(v,depth=0){if(depth>2)return '<span class="muted">…</span>';if(v===null)return '<code>None</code>';if(typeof v==='boolean')return `<code>${v?'True':'False'}</code>`;if(typeof v!=='object')return `<code>${esc(v)}</code>`;if(Array.isArray(v))return `<span class="value-array">[${v.map(x=>valueHTML(x,depth+1)).join(', ')}]</span>`;if(v.kind==='node'||v.kind==='ref')return `<span class="node-token">node(${esc(v.value)})</span>`;if(v.kind==='set')return `<span class="value-array">{${v.items.map(x=>valueHTML(x,depth+1)).join(', ')}}</span>`;if(v.kind==='map')return `<span class="value-array">{${v.entries.map(([k,x])=>`${esc(k)}: ${valueHTML(x,depth+1)}`).join(', ')}}</span>`;if(v.kind==='object')return Object.entries(v.fields).slice(0,8).map(([k,x])=>`<div><small>${esc(k)}</small> ${valueHTML(x,depth+1)}</div>`).join('');return `<code>${esc(JSON.stringify(v))}</code>`;}
function drawBoard(p,e){const v=e.variables;const primary=Object.entries(p.example).find(([k,a])=>Array.isArray(a)&&k!=='operations');if(p.category==='Bit Manipulation'){const pairs=Object.entries(v).filter(([k,x])=>['n','a','b','res','result','mask','carry','xor'].includes(k)&&Number.isInteger(x)).slice(0,3);return `<div class="board-label">32-BIT VIEW</div>${pairs.map(([k,n])=>`<div class="bit-row"><strong>${esc(k)}</strong><div>${(n>>>0).toString(2).padStart(32,'0').split('').map((b,i)=>`<span class="${b==='1'?'on':''}" title="Bit ${31-i}">${b}</span>`).join('')}</div><small>${n}</small></div>`).join('')||'<p>Bit values will appear as execution begins.</p>'}`;}
if(p.runner==='tree'||p.runner==='tree-codec'){const initial=p.example.root||p.example.p; if(Array.isArray(initial))return drawTree(initial,v);}
if(['linked','cycle','random-list'].includes(p.runner)){const chains=Object.entries(v).filter(([k,x])=>x?.kind==='node'&&['head','cur','curr','prev','prevNode','slow','fast','l1','l2','list1','list2','node','tail'].includes(k)).slice(0,3);if(chains.length)return `<div class="board-label">NODE REFERENCES · ARROWS FOLLOW NEXT</div>${chains.map(([k,node])=>{let nodes=[],seen=new Set();while(node?.kind==='node'&&!seen.has(node.identity)&&nodes.length<8){seen.add(node.identity);nodes.push(node.value);node=node.next;}return `<div class="chain-row"><strong>${esc(k)}</strong>${nodes.map(n=>`<span class="chain-node">${esc(n)}</span>`).join('<i>→</i>')}<i>→</i><small>${node?.kind==='ref'?'↺ cycle':node==='…'?'…':'None'}</small></div>`;}).join('')}`;}
if(p.example.adjacency||p.example.edges||p.example.prerequisites||p.example.times||p.example.flights)return drawGraph(p,v);
if(primary&&Array.isArray(primary[1][0])&&['grid','matrix','board','heights'].includes(primary[0])){const grid=Array.isArray(v[primary[0]])?v[primary[0]]:primary[1];const r=v.r??v.row??v.i,c=v.c??v.col??v.j;return `<div class="board-label">${esc(primary[0])} · ${grid.length} × ${grid[0]?.length||0}</div><div class="matrix-board" style="--cols:${grid[0]?.length||1}">${grid.flatMap((row,i)=>row.map((x,j)=>`<div class="matrix-cell ${i===r&&j===c?'current':''} ${x===0||x==='0'||x==='X'?'zero':''}" title="row ${i}, column ${j}">${x===2147483647?'∞':esc(x)}</div>`)).join('')}</div>`;}
if(p.category==='Intervals'&&p.example.intervals){const intervals=Array.isArray(v.intervals)?v.intervals:p.example.intervals;const ranges=intervals.map(x=>Array.isArray(x)?x:[]).filter(x=>x.length===2);const max=Math.max(1,...ranges.flat());return `<div class="board-label">INTERVALS ON A NUMBER LINE</div><div class="interval-board">${ranges.map(([a,b],i)=>`<div class="interval-lane"><span>${i}</span><div><i style="left:${a/max*85}%;width:${Math.max(2,(b-a)/max*85)}%">${a} — ${b}</i></div></div>`).join('')}</div>`;}
let arrayKey=primary?.[0],array=primary?.[1];if(arrayKey&&Array.isArray(v[arrayKey]))array=v[arrayKey];if(!array||Array.isArray(array[0])){const candidate=Object.entries(v).find(([k,a])=>Array.isArray(a)&&!Array.isArray(a[0])&&a.length&&a.length<=25);if(candidate)[arrayKey,array]=candidate;}
if(!array){const str=Object.entries(p.example).find(([k,s])=>typeof s==='string');if(str){arrayKey=str[0];array=(typeof v[arrayKey]==='string'?v[arrayKey]:str[1]).split('');}}
if(array&&array.length<=40&&!Array.isArray(array[0])){const left=v.l??v.left,right=v.r??v.right;const pointers=Object.entries(v).filter(([k,x])=>Number.isInteger(x)&&['i','j','k','l','r','left','right','mid','start','end','slow','fast','index','idx'].includes(k));return `<div class="board-label">${esc(arrayKey||'WORKING ARRAY')} · INDEXED VIEW</div><div class="array-board">${array.map((x,i)=>`<div class="array-cell ${Number.isInteger(left)&&Number.isInteger(right)&&i>=left&&i<=right?'in-window':''} ${pointers.some(([,idx])=>idx===i)?'pointed':''}"><div class="pointer-label">${pointers.filter(([,idx])=>idx===i).map(([k])=>esc(k)).join(' · ')}</div><strong>${typeof x==='object'?valueHTML(x):esc(x)}</strong><small>${i}</small></div>`).join('')}</div>${Number.isInteger(left)&&Number.isInteger(right)?'<div class="window-legend">Highlighted range: current left / right boundaries</div>':''}`;}
const object=v.self?.fields;const map=Object.entries(v).find(([,x])=>x?.kind==='map'||x?.kind==='set');if(object)return `<div class="board-label">DATA STRUCTURE IN MEMORY</div><div class="object-board">${Object.entries(object).slice(0,5).map(([k,x])=>`<div><strong>${esc(k)}</strong>${valueHTML(x)}</div>`).join('')}</div>`;
if(map)return `<div class="board-label">${esc(map[0])} · LOOKUP STATE</div><div class="hash-board">${valueHTML(map[1])}</div>`;
return `<div class="board-label">THE CURRENT QUESTION</div><div class="question-state"><span>${icon(TOPICS[p.category]?.icon||'branch')}</span><strong>${esc(e.function)}()</strong><p>${esc(p.cue)}</p></div>`;}
function drawTree(values,vars){let nodes=[],queue=[];if(values.length&&values[0]!==null){nodes.push({value:values[0],x:50,y:22,parent:null});queue=[0];}let at=1;while(queue.length&&at<values.length){const parent=queue.shift(),n=nodes[parent];for(const side of [-1,1]){if(at>=values.length)break;const value=values[at++];if(value!==null){const level=Math.round((n.y-22)/48)+1;const index=nodes.length;nodes.push({value,x:n.x+side*24/2**(level-1),y:n.y+48,parent});queue.push(index);}}}const active=Object.values(vars).filter(v=>v?.kind==='node').map(v=>v.value);const height=Math.max(110,...nodes.map(n=>n.y+25));return `<div class="board-label">TREE SHAPE · ACTIVE NODE REFERENCES GLOW</div><svg class="tree-board" viewBox="0 0 400 ${height}" role="img" aria-label="Binary tree with current node references highlighted">${nodes.filter(n=>n.parent!==null).map(n=>`<path d="M${nodes[n.parent].x*4} ${nodes[n.parent].y} L${n.x*4} ${n.y}"/>`).join('')}${nodes.map(n=>`<g class="${active.includes(n.value)?'active':''}"><circle cx="${n.x*4}" cy="${n.y}" r="15"/><text x="${n.x*4}" y="${n.y+4}">${n.value}</text></g>`).join('')}</svg>`;}
function drawGraph(p,vars){let edges=[],labels=[];const x=p.example;let directed=false;if(x.adjacency){labels=x.adjacency.map((_,i)=>i+1);x.adjacency.forEach((ns,i)=>ns.forEach(n=>{if(n>i+1)edges.push([i+1,n])}));}else if(x.prerequisites){labels=Array.from({length:x.numCourses},(_,i)=>i);edges=x.prerequisites.map(([a,b])=>[b,a]);directed=true;}else{edges=x.edges||x.times||x.flights;const base=x.times||p.number===684?1:0;labels=Array.from({length:x.n||Math.max(...edges.flatMap(e=>e.slice(0,2)))+1-base},(_,i)=>i+base);directed=!!(x.times||x.flights);}const pos=new Map(labels.map((n,i)=>[n,[200+120*Math.cos(i*2*Math.PI/labels.length-Math.PI/2),105+75*Math.sin(i*2*Math.PI/labels.length-Math.PI/2)]]));const current=vars.node?.value??vars.node??vars.curr??vars.cur??vars.src;return `<div class="board-label">${directed?'DIRECTED':'UNDIRECTED'} GRAPH · ${labels.length} VERTICES</div><svg class="graph-board" viewBox="0 0 400 210" role="img" aria-label="Graph structure"><defs><marker id="graph-arrow" viewBox="0 0 10 10" refX="20" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z"/></marker></defs>${edges.map(([a,b,w])=>{const u=pos.get(a),v=pos.get(b);return u&&v?`<path d="M${u[0]} ${u[1]} L${v[0]} ${v[1]}" ${directed?'marker-end="url(#graph-arrow)"':''}/>${w!==undefined?`<text class="edge-weight" x="${(u[0]+v[0])/2}" y="${(u[1]+v[1])/2-5}">${w}</text>`:''}`:''}).join('')}${labels.map(n=>`<g class="${n===current?'active':''}"><circle cx="${pos.get(n)[0]}" cy="${pos.get(n)[1]}" r="16"/><text x="${pos.get(n)[0]}" y="${pos.get(n)[1]+4}">${n}</text></g>`).join('')}</svg>`;}
function bindLesson(p){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{stop();lessonTab=b.dataset.tab;render()});document.querySelectorAll('[data-approach]').forEach(b=>b.onclick=()=>{approach=+b.dataset.approach;render()});document.querySelectorAll('[data-approach-open]').forEach(b=>b.onclick=()=>{approach=+b.dataset.approachOpen;lessonTab='code';render()});$('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(p.codes[approach]);toast('Python code copied')}catch{toast('Select and copy the code; clipboard is unavailable.')}});$('#note')?.addEventListener('input',e=>{saved.notes[p.id]=e.target.value;$('#note-status').textContent=persist()?'Saved just now · only in this browser':'Session only — export a backup.';});if(bindCinema(p))return;if(bindStory(p))return;const update=()=>{if(!$('#visual'))return;$('#visual').innerHTML=visual(p);$('#scrubber').value=step;$('[data-action="play"]').innerHTML=`${icon(playing?'pause':'play')} ${playing?'Pause':'Play'}`;};$('[data-action="reset"]').onclick=()=>{stop();step=0;update()};$('[data-action="prev"]').onclick=()=>{stop();step=Math.max(0,step-1);update()};$('[data-action="next"]').onclick=()=>{stop();step=Math.min(p.trace.length-1,step+1);update()};const start=()=>{playing=true;clearInterval(timer);timer=setInterval(()=>{step++;if(step>=p.trace.length-1){step=p.trace.length-1;stop()}update()},speed);update()};$('[data-action="play"]').onclick=()=>{if(playing){stop();update()}else{if(step===p.trace.length-1)step=0;start()}};$('#speed').value=String(speed);$('#speed').onchange=e=>{speed=+e.target.value;if(playing)start()};$('#scrubber').oninput=e=>{stop();step=+e.target.value;update()};}
function deck(){let cards=trackData().filter(p=>category==='All'||p.category===category).flatMap(p=>[{id:p.id+'-state',p,q:`${p.title}: what must the algorithm remember?`,a:p.track==='neetcode'?p.approaches[p.recommended].intuition.replace(/[*`]/g,''):p.stateMeaning},{id:p.id+'-pattern',p,q:`What clue points to the pattern in ${p.title}?`,a:p.track==='neetcode'?p.cue:p.intuition[0]+' '+p.notes[0]}]);return flashMode==='review'?cards.filter(c=>saved.reviews[c.id]!=='known'):cards;}
function bindFlash(){legacyBindFlash();}
speed=800;
render();

function library(onlySaved=false){const original=libraryBeforeClassroom(onlySaved);if(onlySaved)return original;const items=trackData(),completed=items.filter(p=>saved.done.includes(p.id)).length,last=items.find(p=>p.id===saved.last)||items.find(p=>!saved.done.includes(p.id))||items[0];return `<div class="classroom-home-heading"><div><div class="eyebrow">YOUR PERSONAL DSA CLASSROOM</div><h1>A little clearer. Every day.</h1><p>${trackName()} · Python · made for understanding</p></div><button class="btn" data-go="notes">${icon('notes')} My notebook</button></div><div class="mobile-track track-switch"><button data-track="neetcode" class="${currentTrack==='neetcode'?'active':''}">NeetCode 150</button><button data-track="dp" class="${currentTrack==='dp'?'active':''}">Striver’s DP</button></div><section class="learning-hero"><div class="learning-hero-copy"><div class="eyebrow">FROM CODE TO A MENTAL PICTURE</div><h2>See the algorithm.<br><em>Understand the idea.</em></h2><p>Follow the objects. Watch the code. Connect every decision to the state it changes.</p><button class="btn" data-go="lesson/${last.id}">${icon('play')} Continue learning ${icon('arrow')}</button></div><div class="learning-hero-art" aria-hidden="true"><div class="hero-state-grid">${[1,1,1,1,1,2,3,4,1,3,6,10].map((n,i)=>`<span class="${i===10?'hero-active':[6,9].includes(i)?'hero-dep':''}">${n}</span>`).join('')}</div><span class="hero-formula">dp[r][c] = top + left</span></div></section><div class="learning-quicklinks"><button data-go="lesson/${currentTrack==='dp'?2:1011}"><span>${icon('play')}</span><div><strong>Step into a 3D lesson</strong><small>Objects, code, and explanation together</small></div></button><button data-go="topics"><span>${icon('book')}</span><div><strong>Build your foundations</strong><small>Understand the pattern before the problem</small></div></button><button data-go="flashcards"><span>${icon('cards')}</span><div><strong>Make it stay with you</strong><small>Recall the idea without looking</small></div></button></div><div class="learning-progress"><span><b>${completed} of ${items.length}</b> lessons understood</span><div><i style="width:${completed/items.length*100}%"></i></div><span>${items.length} interactive 3D lessons</span></div>`+original.slice(original.indexOf('<div class="section-heading">'));}
